<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { api, statusText } from '../api'
import { usePermissions } from '../permissions'
import ModalDialog from '../components/ModalDialog.vue'
import PageState from '../components/PageState.vue'
import FilterSelect from '../components/FilterSelect.vue'

const bundleOptions = computed(() => bundles.value.map(b => ({ value: b.id, label: `扎 ${b.bundle_no} · ${b.color}/${b.size} · ${b.current_qty}件` })))
const warehouseOptions = computed(() => warehouses.value.map(w => ({ value: w.id, label: w.name })))
const inspectionOptions = computed(() => inspections.value.filter(i => i.status === 'confirmed').map(i => ({ value: i.id, label: `${i.inspection_no} · 合格 ${i.passed_qty}` })))
const shipmentProjectOptions = computed(() => projects.value.map(p => ({ value: p.id, label: p.project_code })))

const { has } = usePermissions()
const canMasterdataWrite = computed(() => has('masterdata:write'))
const canWorkOrderWrite = computed(() => has('work_order:write'))

const tab = ref('inspections')
const loading = ref(false)
const saving = ref(false)
const error = ref('')
const notice = ref('')
const modal = ref('')
const inspections = ref<any[]>([])
const receipts = ref<any[]>([])
const shipments = ref<any[]>([])
const bundles = ref<any[]>([])
const warehouses = ref<any[]>([])
const projects = ref<any[]>([])
const returns = ref<any[]>([])
const returnTarget = ref<any>(null)
const returnLines = ref<any[]>([])
const inspectionForm = reactive({ inspection_no: '', bundle_id: '', work_order_id: '', inspected_qty: 1, passed_qty: 1, rework_qty: 0, scrapped_qty: 0 })
const receiptForm = reactive({ receipt_no: '', inspection_id: '', work_order_id: '', bundle_id: '', warehouse_id: '', qty: 1 })
const shipmentForm = reactive({ shipment_no: '', project_id: '', bundle_id: '', qty: 1 })
const returnForm = reactive({ bundle_id: '', qty: 1, reason: '' })
const returnLineOptions = computed(() => returnLines.value.filter((l:any) => Number(l.returnable_qty) > 0).map((l:any) => ({ value: l.bundle_id, label: `扎 ${l.bundle_no} · ${l.color}/${l.size} · 可退 ${l.returnable_qty}` })))
const returnMax = computed(() => Number(returnLines.value.find((l:any) => l.bundle_id === returnForm.bundle_id)?.returnable_qty || 1))
async function load() {
  loading.value = true; error.value = ''
  try {
    const [i, r, s, b, w, p, ret] = await Promise.all([api<{items:any[]}>('/final-inspections'),api<{items:any[]}>('/finished-receipts'),api<{items:any[]}>('/shipments'),api<{items:any[]}>('/bundles'),api<{items:any[]}>('/warehouses'),api<{items:any[]}>('/projects'),api<{items:any[]}>('/shipment-returns')])
    inspections.value=i.items;receipts.value=r.items;shipments.value=s.items;bundles.value=b.items;warehouses.value=w.items;projects.value=p.items;returns.value=ret.items
  } catch(e){error.value=(e as Error).message} finally{loading.value=false}
}
function selectInspectionBundle(){const b=bundles.value.find(x=>x.id===inspectionForm.bundle_id);if(b){inspectionForm.work_order_id=b.work_order_id;inspectionForm.inspected_qty=b.current_qty;inspectionForm.passed_qty=b.current_qty}}
function selectReceiptInspection(){const i=inspections.value.find(x=>x.id===receiptForm.inspection_id);if(i){receiptForm.work_order_id=i.work_order_id;receiptForm.bundle_id=i.bundle_id;receiptForm.qty=i.passed_qty}}
async function createInspection(){saving.value=true;error.value='';try{await api('/final-inspections',{method:'POST',body:JSON.stringify({...inspectionForm,inspected_qty:Number(inspectionForm.inspected_qty),passed_qty:Number(inspectionForm.passed_qty),rework_qty:Number(inspectionForm.rework_qty),scrapped_qty:Number(inspectionForm.scrapped_qty)})});modal.value='';notice.value='总检已保存，请确认后生效';await load()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
async function confirmInspection(item:any){try{await api(`/final-inspections/${item.id}/confirm`,{method:'POST',body:JSON.stringify({version:item.version,remark:''})});notice.value='总检已确认';await load()}catch(e){error.value=(e as Error).message}}
async function createReceipt(){saving.value=true;error.value='';try{await api('/finished-receipts',{method:'POST',body:JSON.stringify({receipt_no:receiptForm.receipt_no,work_order_id:receiptForm.work_order_id,warehouse_id:receiptForm.warehouse_id,lines:[{bundle_id:receiptForm.bundle_id,inspection_id:receiptForm.inspection_id,qty:Number(receiptForm.qty)}]})});modal.value='';notice.value='入库草稿已创建';await load()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
async function receiptAction(item:any,action:string){try{await api(`/finished-receipts/${item.id}/${action}`,{method:'POST',body:JSON.stringify({version:item.version,remark:''})});notice.value='入库状态已更新';await load()}catch(e){error.value=(e as Error).message}}
async function createShipment(){const b=bundles.value.find(x=>x.id===shipmentForm.bundle_id);if(!b){error.value='请选择出货扎';return};saving.value=true;error.value='';try{await api('/shipments',{method:'POST',body:JSON.stringify({shipment_no:shipmentForm.shipment_no,project_id:shipmentForm.project_id,lines:[{work_order_id:b.work_order_id,bundle_id:b.id,color:b.color,size:b.size,qty:Number(shipmentForm.qty)}]})});modal.value='';notice.value='出货草稿已创建';await load()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
async function confirmShipment(item:any){try{await api(`/shipments/${item.id}/confirm`,{method:'POST',body:JSON.stringify({version:item.version})});notice.value='出货已确认，项目未出货数已更新';await load()}catch(e){error.value=(e as Error).message}}
async function createWarehouse(){const code=window.prompt('请输入成品仓编码');if(!code)return;const name=window.prompt('请输入仓库名称');if(!name)return;try{await api('/warehouses',{method:'POST',body:JSON.stringify({code,name,warehouse_type:'finished'})});notice.value='成品仓已创建';await load()}catch(e){error.value=(e as Error).message}}
async function openReturn(item:any){returnTarget.value=item;returnForm.bundle_id='';returnForm.qty=1;returnForm.reason='';returnLines.value=[];error.value='';try{const data=await api<any>(`/shipments/${item.id}`);returnLines.value=data.lines||[];const first=returnLines.value.find((l:any)=>Number(l.returnable_qty)>0);if(first){returnForm.bundle_id=first.bundle_id;returnForm.qty=Number(first.returnable_qty)}modal.value='return'}catch(e){error.value=(e as Error).message}}
async function createReturn(){if(!returnTarget.value||!returnForm.bundle_id||Number(returnForm.qty)<=0||!returnForm.reason.trim()){error.value='扎、退货数量和原因必填';return}saving.value=true;error.value='';try{await api(`/shipments/${returnTarget.value.id}/returns`,{method:'POST',body:JSON.stringify({bundle_id:returnForm.bundle_id,qty:Number(returnForm.qty),reason:returnForm.reason})});modal.value='';returnTarget.value=null;notice.value='退货已提交，成品库存已回补';await load()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
onMounted(load)
</script>
<template>
<div class="page-header"><div><h1>质量、成品与出货</h1><p>总检守恒、三方入库复核和库存出货全流程</p></div><div class="header-actions"><button v-if="canMasterdataWrite" class="button secondary" @click="createWarehouse">+ 仓库</button><button v-if="canWorkOrderWrite" class="button secondary" @click="modal='inspection'">+ 总检</button><button v-if="canWorkOrderWrite" class="button secondary" @click="modal='receipt'">+ 入库</button><button v-if="canWorkOrderWrite" class="button" @click="modal='shipment'">+ 出货</button></div></div><div v-if="error" class="notice error">{{error}}</div><div v-if="notice" class="notice success">{{notice}}</div>
<section class="panel"><div class="tabs"><button :class="{active:tab==='inspections'}" @click="tab='inspections'">总检记录</button><button :class="{active:tab==='receipts'}" @click="tab='receipts'">成品入库</button><button :class="{active:tab==='shipments'}" @click="tab='shipments'">出货单</button><button :class="{active:tab==='returns'}" @click="tab='returns'">退货记录</button></div><PageState :loading="loading"/>
<div v-if="!loading&&tab==='inspections'" class="table-wrap"><table><thead><tr><th>总检单号</th><th>检验数</th><th>合格</th><th>返工</th><th>报废</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in inspections"><td>{{item.inspection_no}}</td><td>{{item.inspected_qty}}</td><td>{{item.passed_qty}}</td><td>{{item.rework_qty}}</td><td>{{item.scrapped_qty}}</td><td><span class="status" :class="item.status">{{statusText[item.status]||item.status}}</span></td><td><button v-if="item.status==='pending'" class="button link" @click="confirmInspection(item)">确认</button></td></tr></tbody></table><PageState :empty="!inspections.length"/></div>
<div v-if="!loading&&tab==='receipts'" class="table-wrap"><table><thead><tr><th>入库单号</th><th>数量</th><th>状态</th><th>三方流转</th></tr></thead><tbody><tr v-for="item in receipts"><td>{{item.receipt_no}}</td><td>{{item.qty}}</td><td><span class="status" :class="item.status">{{statusText[item.status]||item.status}}</span></td><td><button v-if="item.status==='draft'" class="button link" @click="receiptAction(item,'submit')">提交总检</button><button v-if="item.status==='pending_quality'" class="button link" @click="receiptAction(item,'confirm-quality')">总检确认</button><button v-if="item.status==='pending_review'" class="button link" @click="receiptAction(item,'approve')">复核生效</button><span v-if="item.status==='approved'" class="text-muted">库存流水已生成</span></td></tr></tbody></table><PageState :empty="!receipts.length"/></div>
<div v-if="!loading&&tab==='shipments'" class="table-wrap"><table><thead><tr><th>出货单号</th><th>数量</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in shipments"><td>{{item.shipment_no}}</td><td>{{item.qty}}</td><td><span class="status" :class="item.status">{{statusText[item.status]||item.status}}</span></td><td><button v-if="item.status==='draft'" class="button link" @click="confirmShipment(item)">确认出货</button><button v-if="item.status==='confirmed'" class="button link text-danger" @click="openReturn(item)">退货</button></td></tr></tbody></table><PageState :empty="!shipments.length"/></div>
<div v-if="!loading&&tab==='returns'" class="table-wrap"><table><thead><tr><th>退货单号</th><th>出货单</th><th>项目</th><th>工单</th><th>扎号</th><th>颜色/尺码</th><th>退货数</th><th>原因</th><th>状态</th></tr></thead><tbody><tr v-for="item in returns"><td><strong>{{item.return_no}}</strong></td><td>{{item.shipment_no}}</td><td>{{item.project_code}}</td><td>{{item.work_order_code}}</td><td>{{item.bundle_no}}</td><td>{{item.color}}/{{item.size}}</td><td>{{item.qty}}</td><td>{{item.reason}}</td><td><span class="status" :class="item.status">{{statusText[item.status]||item.status}}</span></td></tr></tbody></table><PageState :empty="!returns.length"/></div></section>
<ModalDialog v-if="modal==='inspection'" title="录入总检" @close="modal=''"><div class="form-grid"><div class="field full"><label class="required">总检单号</label><input v-model.trim="inspectionForm.inspection_no"></div><div class="field full"><label class="required">生产扎</label><FilterSelect v-model="inspectionForm.bundle_id" :options="bundleOptions" @change="selectInspectionBundle"/></div><div class="field"><label>总检数</label><input v-model.number="inspectionForm.inspected_qty" type="number" min="1"></div><div class="field"><label>合格</label><input v-model.number="inspectionForm.passed_qty" type="number" min="0"></div><div class="field"><label>返工</label><input v-model.number="inspectionForm.rework_qty" type="number" min="0"></div><div class="field"><label>报废</label><input v-model.number="inspectionForm.scrapped_qty" type="number" min="0"></div></div><div class="notice">数量合计：{{Number(inspectionForm.passed_qty)+Number(inspectionForm.rework_qty)+Number(inspectionForm.scrapped_qty)}} / 总检 {{inspectionForm.inspected_qty}}</div><template #footer><button class="button secondary" @click="modal=''">取消</button><button class="button" :disabled="saving||inspectionForm.inspected_qty!==inspectionForm.passed_qty+inspectionForm.rework_qty+inspectionForm.scrapped_qty" @click="createInspection">保存</button></template></ModalDialog>
<ModalDialog v-if="modal==='receipt'" title="成品入库填单" @close="modal=''"><div class="form-grid"><div class="field full"><label class="required">入库单号</label><input v-model.trim="receiptForm.receipt_no"></div><div class="field full"><label class="required">关联已确认总检</label><FilterSelect v-model="receiptForm.inspection_id" :options="inspectionOptions" @change="selectReceiptInspection"/></div><div class="field"><label>仓库</label><FilterSelect v-model="receiptForm.warehouse_id" :options="warehouseOptions"/></div><div class="field"><label>本次入库数量</label><input v-model.number="receiptForm.qty" type="number" min="1"></div></div><template #footer><button class="button secondary" @click="modal=''">取消</button><button class="button" :disabled="saving" @click="createReceipt">保存草稿</button></template></ModalDialog>
<ModalDialog v-if="modal==='shipment'" title="新建出货单" @close="modal=''"><div class="form-grid"><div class="field full"><label class="required">出货单号</label><input v-model.trim="shipmentForm.shipment_no"></div><div class="field"><label>项目</label><FilterSelect v-model="shipmentForm.project_id" :options="shipmentProjectOptions"/></div><div class="field"><label>出货扎</label><FilterSelect v-model="shipmentForm.bundle_id" :options="bundleOptions"/></div><div class="field"><label>出货数量</label><input v-model.number="shipmentForm.qty" type="number" min="1"></div></div><template #footer><button class="button secondary" @click="modal=''">取消</button><button class="button" :disabled="saving" @click="createShipment">保存草稿</button></template></ModalDialog>
<ModalDialog v-if="modal==='return'" :title="`出货退货 · ${returnTarget?.shipment_no || ''}`" @close="modal=''"><div v-if="error" class="notice error">{{error}}</div><div class="form-grid"><div class="field full"><label class="required">退货扎</label><FilterSelect v-model="returnForm.bundle_id" :options="returnLineOptions" placeholder="选择可退扎"/></div><div class="field"><label class="required">退货数量</label><input v-model.number="returnForm.qty" type="number" min="1" :max="returnMax"></div><div class="field full"><label class="required">退货原因</label><input v-model.trim="returnForm.reason" placeholder="如 客户部分退货"></div></div><div class="notice">退货会写正向成品库存流水；可退数量为该扎已出货数减已退货数。整单退货时填写全部可退数量。</div><template #footer><button class="button secondary" @click="modal=''">取消</button><button class="button" :disabled="saving || !returnForm.bundle_id || Number(returnForm.qty) <= 0 || !returnForm.reason.trim()" @click="createReturn">确认退货</button></template></ModalDialog>
</template>
